"""Acceso SQLite y creación inicial del esquema."""
import os
import re
import sqlite3

from flask import current_app, g
from werkzeug.security import generate_password_hash


class PostgreSQLConnection:
    """Adapta las consultas DB-API existentes al controlador psycopg."""

    backend = "postgresql"

    def __init__(self, connection):
        self.connection = connection

    def execute(self, sql, args=()):
        sql = re.sub(r"\bINTEGER PRIMARY KEY AUTOINCREMENT\b",
                     "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY", sql, flags=re.IGNORECASE)
        sql = re.sub(r"\bINTEGER\b", "BIGINT", sql, flags=re.IGNORECASE)
        sql = re.sub(r"\bREAL\b", "DOUBLE PRECISION", sql, flags=re.IGNORECASE)
        ignore_conflicts = bool(re.search(r"\bINSERT\s+OR\s+IGNORE\s+INTO\b", sql, flags=re.IGNORECASE))
        sql = re.sub(r"\bINSERT\s+OR\s+IGNORE\s+INTO\b", "INSERT INTO", sql, flags=re.IGNORECASE)
        sql = sql.replace("%", "%%")
        sql = sql.replace("?", "%s")
        sql = re.sub(r"\bLIKE\b", "ILIKE", sql, flags=re.IGNORECASE)
        sql = re.sub(
            r"\b([A-Za-z_]\w*)\s*=\s*(%s)\s+COLLATE\s+NOCASE\b",
            r"LOWER(\1) = LOWER(\2)", sql, flags=re.IGNORECASE,
        )
        if ignore_conflicts:
            sql = sql.rstrip().rstrip(";") + " ON CONFLICT DO NOTHING"
        return self.connection.execute(sql, args)

    def executescript(self, script):
        script = re.sub(r"(?m)^\s*--.*(?:\n|$)", "", script)
        script = re.sub(r"(?im)^\s*PRAGMA\s+foreign_keys\s*=\s*ON\s*;\s*$", "", script)
        for statement in script.split(";"):
            if statement.strip():
                self.execute(statement)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if exc_type is None:
            self.connection.commit()
        else:
            self.connection.rollback()
        return False

    def __getattr__(self, name):
        return getattr(self.connection, name)


def get_db():
    """Devuelve la conexión SQLite configurada para la petición actual."""
    if "db" not in g:
        database_path = current_app.config["DATABASE_PATH"]
        if database_path != ":memory:":
            os.makedirs(os.path.dirname(os.path.abspath(database_path)), exist_ok=True)
        g.db = sqlite3.connect(database_path, timeout=30)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
        g.db.execute("PRAGMA busy_timeout = 30000")
    return g.db


def close_db(e=None):
    """Cierra la conexión al terminar la petición."""
    db = g.pop("db", None)
    if db is not None:
        db.close()


def query(sql, args=(), one=False):
    """Ejecuta un SELECT. Con one=True devuelve la primera fila (o None)."""
    rows = get_db().execute(sql, args).fetchall()
    if one:
        return rows[0] if rows else None
    return rows


def init_app(app):
    """Registra el cierre automático de la conexión en la aplicación."""
    app.teardown_appcontext(close_db)


def is_postgresql(db):
    return getattr(db, "backend", None) == "postgresql"


def table_columns(db, table):
    """Devuelve los nombres de columna de una conexión SQLite o PostgreSQL."""
    if is_postgresql(db):
        return {r["name"] for r in db.execute(
            "SELECT column_name AS name FROM information_schema.columns "
            "WHERE table_schema = current_schema() AND table_name = ?", (table,)
        ).fetchall()}
    return {row["name"] for row in db.execute(f'PRAGMA table_info("{table}")').fetchall()}


def table_exists(db, table):
    if is_postgresql(db):
        return bool(db.execute(
            "SELECT 1 FROM information_schema.tables "
            "WHERE table_schema = current_schema() AND table_name = ?", (table,)
        ).fetchone())
    return bool(db.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?", (table,)
    ).fetchone())


# Valores por defecto de la tabla de configuración
CONFIG_POR_DEFECTO = {
    "empresa_nombre": "FTI Import",
    "empresa_rif": "",
    "empresa_direccion": "",
    "empresa_telefono": "",
    "contado_requiere_aprobacion": "0",   # 0 = las ventas de contado se aprueban solas
    "dias_por_vencer": "3",               # días de aviso antes del vencimiento
    "stock_alerta_defecto": "10",         # alerta mínima de stock (para productos sin mínimo propio)
}


def migrar_roles_y_colores(db):
    """Agrega a una base de datos existente el tipo de vendedor y el color de cliente.

    Los vendedores que ya existían pasan a ser 'especial' (conservan todo lo que podían hacer).
    Es idempotente: si las columnas ya existen no hace nada.
    """
    cols_u = table_columns(db, "usuarios")
    if not cols_u:        # base vacía: la creará init_db con el esquema completo
        return
    if "tipo_vendedor" not in cols_u:
        # El DEFAULT 'especial' solo sirve para convertir a los vendedores ya creados;
        # todo alta nueva indica el tipo de forma explícita.
        db.execute("ALTER TABLE usuarios ADD COLUMN tipo_vendedor TEXT NOT NULL DEFAULT 'especial' "
                   "CHECK (tipo_vendedor IN ('especial', 'normal'))")
    cols_c = table_columns(db, "clientes")
    if "color" not in cols_c:
        db.execute("ALTER TABLE clientes ADD COLUMN color TEXT DEFAULT NULL "
                   "CHECK (color IN ('verde', 'amarillo', 'rojo'))")
    db.execute("INSERT OR IGNORE INTO configuracion(clave, valor) VALUES ('stock_alerta_defecto', '10')")
    migrar_armados_y_precios(db)
    migrar_presupuestos(db)
    migrar_suscripciones_notificaciones(db)
    db.commit()


def migrar_suscripciones_notificaciones(db):
    """Crea la tabla de suscripciones Web Push en bases existentes."""
    db.execute("""CREATE TABLE IF NOT EXISTS notificaciones_push (
        endpoint TEXT PRIMARY KEY,
        usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
        clave_publica TEXT NOT NULL,
        clave_auth TEXT NOT NULL,
        creado TEXT NOT NULL
    )""")


def migrar_armados_y_precios(db):
    """Crea (si faltan) las tablas del historial de precios de 48 h y de los pedidos para armar.

    Las ventas que ya existían antes de esta función NO exigen armado (config 'armado_desde_venta'):
    solo las ventas nuevas muestran "aún no se ha armado". Es idempotente.
    """
    db.executescript("""
    CREATE TABLE IF NOT EXISTS precio_cambios (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        producto_id INTEGER NOT NULL REFERENCES productos(id),
        usuario_id INTEGER REFERENCES usuarios(id),
        fecha TEXT NOT NULL, expira TEXT NOT NULL,
        mayor_ant REAL NOT NULL, mayor_nuevo REAL NOT NULL);
    CREATE INDEX IF NOT EXISTS ix_precio_cambios ON precio_cambios(expira, producto_id);
    CREATE TABLE IF NOT EXISTS armados (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        venta_id INTEGER NOT NULL UNIQUE REFERENCES ventas(id),
        asignado_a INTEGER REFERENCES usuarios(id),
        estado TEXT NOT NULL DEFAULT 'pendiente' CHECK (estado IN ('pendiente', 'armado')),
        asignado_por INTEGER REFERENCES usuarios(id),
        fecha_asignacion TEXT NOT NULL,
        armado_por INTEGER REFERENCES usuarios(id),
        fecha_armado TEXT,
        fecha_salida TEXT);
    CREATE INDEX IF NOT EXISTS ix_armados_estado ON armados(estado, asignado_a);
    """)
    if "fecha_salida" not in table_columns(db, "armados"):
        db.execute("ALTER TABLE armados ADD COLUMN fecha_salida TEXT")
    db.execute("INSERT OR IGNORE INTO configuracion(clave, valor) "
               "VALUES ('armado_desde_venta', CAST(COALESCE((SELECT MAX(id) FROM ventas), 0) AS TEXT))")


def migrar_presupuestos(db):
    """Crea las tablas de presupuestos guardados por vendedor y cliente."""
    db.executescript("""
    CREATE TABLE IF NOT EXISTS presupuestos (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        vendedor_id INTEGER NOT NULL REFERENCES usuarios(id),
        cliente_id INTEGER NOT NULL REFERENCES clientes(id),
        creado TEXT NOT NULL,
        actualizado TEXT NOT NULL,
        tipo_pago TEXT NOT NULL DEFAULT 'contado' CHECK (tipo_pago IN ('contado', 'credito')),
        metodo_pago TEXT DEFAULT '',
        cuota_inicial REAL NOT NULL DEFAULT 0,
        subtotal REAL NOT NULL DEFAULT 0,
        descuento_porcentaje INTEGER NOT NULL DEFAULT 0,
        descuento REAL NOT NULL DEFAULT 0,
        total REAL NOT NULL DEFAULT 0,
        nota TEXT DEFAULT '',
        venta_id INTEGER REFERENCES ventas(id));
    CREATE INDEX IF NOT EXISTS ix_presupuestos_vendedor ON presupuestos(vendedor_id, actualizado);
    CREATE INDEX IF NOT EXISTS ix_presupuestos_cliente ON presupuestos(cliente_id, actualizado);
    CREATE TABLE IF NOT EXISTS presupuesto_detalles (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        presupuesto_id INTEGER NOT NULL REFERENCES presupuestos(id) ON DELETE CASCADE,
        producto_id INTEGER NOT NULL REFERENCES productos(id),
        cantidad REAL NOT NULL,
        precio_lista REAL NOT NULL,
        precio_unit REAL NOT NULL,
        modificado INTEGER NOT NULL DEFAULT 0,
        subtotal REAL NOT NULL);
    CREATE INDEX IF NOT EXISTS ix_presupuesto_detalles ON presupuesto_detalles(presupuesto_id);
    """)
    for tabla in ("ventas", "presupuestos"):
        columnas = table_columns(db, tabla)
        if "descuento_porcentaje" not in columnas:
            db.execute(
                f"ALTER TABLE {tabla} ADD COLUMN descuento_porcentaje INTEGER NOT NULL DEFAULT 0"
            )
            db.execute(
                f"""UPDATE {tabla}
                       SET descuento_porcentaje = CASE
                           WHEN subtotal <= 0 OR descuento <= 0 THEN 0
                           WHEN descuento >= subtotal THEN 100
                           ELSE CAST(ROUND(descuento * 100.0 / subtotal) AS INTEGER)
                       END"""
            )


def migrar_solo_mayor(db):
    """Elimina los campos de precio detal y el tipo de precio de la base existente."""
    columnas_productos = table_columns(db, "productos")
    columnas_precios = table_columns(db, "precio_cambios")
    columnas_ventas = table_columns(db, "ventas")
    necesita_migrar_ventas = "tipo_precio" in columnas_ventas
    if not ({"precio_detal_usd"} & columnas_productos or
            {"detal_ant", "detal_nuevo"} & columnas_precios or necesita_migrar_ventas):
        return

    if is_postgresql(db):
        for tabla, columnas in (
            ("productos", ("precio_detal_usd",)),
            ("precio_cambios", ("detal_ant", "detal_nuevo")),
            ("ventas", ("tipo_precio",)),
        ):
            existentes = table_columns(db, tabla)
            for columna in columnas:
                if columna in existentes:
                    db.execute(f"ALTER TABLE {tabla} DROP COLUMN {columna}")
        db.commit()
        return

    db.commit()
    db.execute("PRAGMA foreign_keys = OFF")
    try:
        db.execute("BEGIN IMMEDIATE")
        if "precio_detal_usd" in columnas_productos:
            db.execute("ALTER TABLE productos DROP COLUMN precio_detal_usd")
        for columna in ("detal_ant", "detal_nuevo"):
            if columna in columnas_precios:
                db.execute(f"ALTER TABLE precio_cambios DROP COLUMN {columna}")
        if necesita_migrar_ventas:
            db.execute("""
                CREATE TABLE ventas_solo_mayor (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    numero TEXT,
                    fecha TEXT NOT NULL,
                    cliente_id INTEGER NOT NULL REFERENCES clientes(id),
                    vendedor_id INTEGER NOT NULL REFERENCES usuarios(id),
                    tipo_pago TEXT NOT NULL CHECK (tipo_pago IN ('contado', 'credito')),
                    dias_credito INTEGER NOT NULL DEFAULT 0,
                    moneda TEXT NOT NULL CHECK (moneda IN ('USD', 'VES')),
                    tasa REAL NOT NULL DEFAULT 1,
                    metodo_pago TEXT DEFAULT '',
                    subtotal REAL NOT NULL DEFAULT 0,
                    descuento_porcentaje INTEGER NOT NULL DEFAULT 0,
                    descuento REAL NOT NULL DEFAULT 0,
                    total REAL NOT NULL DEFAULT 0,
                    total_usd REAL NOT NULL DEFAULT 0,
                    estado TEXT NOT NULL DEFAULT 'pendiente'
                           CHECK (estado IN ('pendiente', 'aprobada', 'rechazada', 'anulada')),
                    pagada INTEGER NOT NULL DEFAULT 0,
                    nota TEXT DEFAULT '',
                    aprobado_por INTEGER REFERENCES usuarios(id),
                    fecha_aprobacion TEXT,
                    motivo TEXT DEFAULT ''
                )
            """)
            columnas = [r["name"] for r in db.execute("PRAGMA table_info(ventas)")
                        if r["name"] != "tipo_precio"]
            nombres = ", ".join(columnas)
            db.execute(f"INSERT INTO ventas_solo_mayor ({nombres}) SELECT {nombres} FROM ventas")
            db.execute("DROP TABLE ventas")
            db.execute("ALTER TABLE ventas_solo_mayor RENAME TO ventas")
            db.execute("CREATE INDEX IF NOT EXISTS ix_ventas_vendedor ON ventas(vendedor_id, estado)")
        db.commit()
    except Exception:
        db.rollback()
        raise
    finally:
        db.execute("PRAGMA foreign_keys = ON")
    incumplimientos = db.execute("PRAGMA foreign_key_check").fetchall()
    if incumplimientos:
        raise sqlite3.IntegrityError("La migración de ventas dejó referencias inválidas.")


def init_db(demo=False):
    """Crea las tablas, la configuración base y el usuario admin inicial.

    Con demo=True agrega categorías, productos, un vendedor y clientes de ejemplo.
    Requiere un contexto de aplicación activo.
    """
    from utils import ahora  # import local para evitar ciclos

    db = get_db()
    ruta = os.path.join(os.path.dirname(os.path.abspath(__file__)), "schema.sql")
    with open(ruta, encoding="utf-8") as f:
        db.executescript(f.read())
    # Migraciones compatibles con bases de datos existentes.
    columnas = table_columns(db, "productos")
    if "imagen" not in columnas:
        db.execute("ALTER TABLE productos ADD COLUMN imagen TEXT DEFAULT NULL")
    columnas_cat = table_columns(db, "categorias")
    if "prefijo" not in columnas_cat:
        db.execute("ALTER TABLE categorias ADD COLUMN prefijo TEXT")
    # Las categorías ya NO llevan código automático: solo nombre (el código lo escribe el admin en cada producto).
    migrar_roles_y_colores(db)
    migrar_solo_mayor(db)
    db.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_categorias_prefijo ON categorias(prefijo) WHERE prefijo IS NOT NULL")
    db.execute("""CREATE TABLE IF NOT EXISTS archivos_historicos (
        id INTEGER PRIMARY KEY AUTOINCREMENT, titulo TEXT NOT NULL, tipo TEXT NOT NULL,
        desde TEXT NOT NULL, hasta TEXT NOT NULL, generado TEXT NOT NULL, ruta TEXT NOT NULL,
        usuario_id INTEGER REFERENCES usuarios(id), estado TEXT NOT NULL DEFAULT 'listo')""")

    # Configuración por defecto (no pisa valores existentes)
    for clave, valor in CONFIG_POR_DEFECTO.items():
        db.execute("INSERT OR IGNORE INTO configuracion(clave, valor) VALUES (?, ?)", (clave, valor))

    # Admin inicial si no existe ninguno
    hay_admin = db.execute("SELECT 1 FROM usuarios WHERE rol = 'admin'").fetchone()
    if not hay_admin:
        clave_inicial = os.environ.get("INITIAL_ADMIN_PASSWORD")
        if not clave_inicial:
            raise RuntimeError(
                "Define INITIAL_ADMIN_PASSWORD antes de inicializar una base sin administrador."
            )
        db.execute(
            "INSERT INTO usuarios (usuario, nombre, clave_hash, rol, creado) VALUES (?,?,?,?,?)",
            ("admin", "Administrador", generate_password_hash(clave_inicial), "admin", ahora()),
        )

    if demo:
        _datos_demo(db)
    db.commit()


